const $=id=>document.getElementById(id);
let mode='login',user=null,items=[],accounts=[],sourceSections=[],activeView='overview',activeBank=null,accountingTemplate=null,showMonthSpend=false,plannedBills=[],subscriptions=[],positions=[];
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n||0));
const api=async(url,opt={})=>{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(url,{...opt,signal:controller.signal,headers:{'Content-Type':'application/json',...(opt.headers||{})},credentials:'same-origin'});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}catch(e){if(e?.name==='AbortError')throw Error('Request timed out. Please retry.');throw e}finally{clearTimeout(timer)}};
function setMode(m){mode=m;$('loginTab').classList.toggle('active',m==='login');$('registerTab').classList.toggle('active',m==='register');$('forgotTab').classList.toggle('active',m==='forgot');$('secretWrap').classList.toggle('hidden',m==='login');$('authSubmit').textContent=m==='login'?'Sign in securely':m==='register'?'Create private ledger':'Reset password';$('password').autocomplete=m==='login'?'current-password':'new-password';$('password').placeholder=m==='forgot'?'Enter your new password (10+ characters)':'At least 10 characters';$('authMsg').textContent=''}
$('loginTab').onclick=()=>setMode('login');$('registerTab').onclick=()=>setMode('register');$('forgotTab').onclick=()=>setMode('forgot');
$('authForm').onsubmit=async e=>{e.preventDefault();$('authMsg').textContent='';try{const payload={email:$('email').value,password:$('password').value,secretKey:$('secretKey').value};const d=await api('/api/auth?action='+mode,{method:'POST',body:JSON.stringify(payload)});if(mode==='forgot'){setMode('login');$('authMsg').textContent='Password reset. Please sign in.';return}user=d.user;await showApp()}catch(x){$('authMsg').textContent=x.message}};
async function showApp(){$('auth').classList.add('hidden');$('app').classList.remove('hidden');if($('logout'))$('logout').classList.remove('hidden');const who=$('who');if(who)who.textContent=user.email+(user.role==='admin'?' · OWNER / ADMIN':'');$('sourceNav').classList.toggle('hidden',user.role!=='admin');try{renderTopWealth();renderView('overview')}catch(e){console.error('[wealth-startup:dashboard]',e);$('viewContent').innerHTML='<p class="error">Dashboard rendering failed: '+esc(e?.message||'Unknown error')+'</p>'}try{await loadDashboard();renderTopWealth();renderView(activeView)}catch(e){const message=e?.message||'Unknown dashboard error';console.error('[wealth-startup:dashboard-data]',e);$('globalMsg').textContent='Your account is verified, but dashboard loading failed: '+message;$('entries').innerHTML='<p class="error">Dashboard unavailable: '+esc(message)+'</p>'}}
function applyLedgerData(d){items=d.transactions||[];const sum=k=>items.filter(x=>x.kind===k).reduce((a,x)=>a+Number(x.amount),0);$('count').textContent=items.length+' entries';$('entries').innerHTML=items.length?items.map(x=>{const sign=x.kind==='income'?'+':x.kind==='expense'?'-':'';return '<div class="entry"><div><b>'+esc(x.category)+'</b><small>'+esc(x.description||x.kind)+' · '+esc(x.account||'No account')+' · '+esc(String(x.occurred_on).slice(0,10))+'</small></div><span class="value '+(x.kind==='income'?'income':x.kind==='expense'?'expense':'')+'">'+sign+money(x.amount)+'</span><button class="delete" data-id="'+x.id+'" aria-label="Delete entry">×</button></div>'}).join(''):'<p class="muted">No entries yet. Add your first transaction.</p>';$('entries').querySelectorAll('.delete').forEach(b=>b.onclick=async()=>{if(confirm('Delete this ledger entry?')){await api('/api/ledger?id='+encodeURIComponent(b.dataset.id),{method:'DELETE'});await load()}})}
async function load(){applyLedgerData(await api('/api/ledger'))}
async function loadDashboard(){const d=await api('/api/dashboard');applyLedgerData({transactions:d.transactions||[]});const billData=await api('/api/planned-bills');plannedBills=billData.bills||[];subscriptions=billData.subscriptions||[];accountingTemplate=d.template||null;accounts=d.accounts||[];positions=d.positions||[];const accountInput=$('account');if(accountInput&&accountInput.tagName==='SELECT'){accountInput.innerHTML='<option value="">Unassigned / unknown</option>'+accounts.map(a=>'<option value="'+esc(a.account_name+(a.masked_identifier?' '+a.masked_identifier:''))+'">'+esc(a.bank_name+' · '+a.account_name+(a.masked_identifier?' '+a.masked_identifier:''))+'</option>').join('')}window.__wealthSnapshots=d.snapshots||[];window.__wealthSnapshots=d.snapshots||[];sourceSections=[];(d.snapshots||[]).forEach(snap=>{let p=snap.payload;if(typeof p==='string'){try{p=JSON.parse(p)}catch{p={}}}(p.sections||[]).forEach(s=>sourceSections.push({...s,_source:snap.source_name,_date:String(snap.snapshot_date||'').slice(0,10)}))});$('snapshotStatus').textContent=sourceSections.length+' source sections · '+(d.snapshots||[]).length+' saved snapshots';$('sourceCount').textContent=sourceSections.length+' imported sections'}

function subscriptionsHtml(){if(!subscriptions.length)return '';return '<section class="chart-card planned-bills"><div class="chart-head"><div><h4>Active subscriptions & mandates</h4><p>Recurring authorisations · not recorded as paid expenses</p></div><span class="pill">'+subscriptions.length+' active</span></div><div class="planned-bill-list">'+subscriptions.map(s=>'<article class="planned-bill-row"><div class="planned-bill-main"><b>'+esc(s.provider_name)+'</b><small>'+esc(s.bank_name||'Source account')+' · '+esc(s.masked_identifier||'')+'</small><small>'+esc(s.frequency==='as_presented'?'As presented':s.frequency==='frequency_not_confirmed'?'Frequency not confirmed':s.frequency)+(s.merchant_id?' · '+esc(s.merchant_id):'')+'</small></div><div class="planned-bill-actions"><strong>'+(s.amount==null?'Variable':money(s.amount)+(s.amount_type==='up_to'?' max':''))+'</strong><span class="pill">Active</span></div></article>').join('')+'</div></section>'}
function alertsBannerHtml(){const today=new Date();today.setHours(0,0,0,0);const due=plannedBills.filter(b=>{if(b.status!=='planned')return false;const d=new Date(String(b.due_date).slice(0,10)+'T00:00:00');return Math.round((d-today)/86400000)<=5});if(!due.length)return '<button type="button" class="dashboard-alert-banner quiet" data-view="alerts"><span class="dashboard-alert-icon">✓</span><span class="dashboard-alert-copy"><b>No bills due soon</b><small>Alerts · upcoming payments and low-balance checks</small></span><span class="dashboard-alert-arrow">View</span></button>';const total=due.reduce((n,b)=>n+Number(b.amount||0),0);const names=due.slice(0,2).map(b=>esc(b.title)).join(' · ')+(due.length>2?' + '+(due.length-2)+' more':'');return '<button type="button" class="dashboard-alert-banner" data-view="alerts"><span class="dashboard-alert-icon">!</span><span class="dashboard-alert-copy"><b>'+due.length+' payment alert'+(due.length===1?'':'s')+' · '+money(total)+'</b><small>'+names+'</small><small>Due within 5 days or overdue · Tap to view all alerts</small></span><span class="dashboard-alert-arrow">View</span></button>'}
function plannedBillsHtml(){const today=new Date();today.setHours(0,0,0,0);const upcoming=plannedBills.filter(b=>{if(b.status!=='planned')return false;const due=new Date(String(b.due_date).slice(0,10)+'T00:00:00');return Math.round((due-today)/86400000)<=5});if(!upcoming.length)return '<section class="chart-card planned-bills"><div class="chart-head"><div><h4>Planned bills</h4><p>No upcoming bills</p></div></div></section>';return '<section class="chart-card planned-bills"><div class="chart-head"><div><h4>Planned bills</h4><p>Due within 5 days · overdue unpaid bills included · not counted as spending</p></div><span class="pill">'+upcoming.length+' planned</span></div><div class="planned-bill-list">'+upcoming.map(b=>{const due=new Date(String(b.due_date).slice(0,10)+'T00:00:00');const days=Math.round((due-today)/86400000);const label=days<0?Math.abs(days)+' days overdue':days===0?'Due today':'Due in '+days+' days';const balance=Number(b.current_balance),fresh=!!b.current_balance&&b.balance_status==='verified';const after=balance-Number(b.amount);const low=fresh&&(balance<Number(b.amount)||after<500);const balanceHtml=fresh?'<small class="planned-bill-balance '+(low?'low':'')+'">Bank balance: '+money(balance)+' · After premium: '+money(after)+(low?' · LOW BALANCE — add funds':'')+'</small>':'<small class="planned-bill-balance uncertain">Bank balance needs verification ('+esc(b.balance_status||'unknown')+')</small>';return '<article class="planned-bill-row"><div class="planned-bill-main"><b>'+esc(b.title)+'</b><small>'+esc(b.payee||b.category)+' · '+esc(b.bank_name||'Bank account')+' '+esc(b.masked_identifier||'')+' · '+esc(String(b.due_date).slice(0,10))+'</small><small>'+esc(label)+' · '+esc(b.recurrence==='one_time'?'One-time reminder':'Recurrence to be set')+'</small>'+balanceHtml+'</div><div class="planned-bill-actions"><strong>'+money(b.amount)+'</strong>'+(low?'<span class="pill warning">Low balance</span>':'')+'<button type="button" class="ghost" data-bill-paid="'+esc(b.id)+'">Mark paid</button></div></article>'}).join('')+'</div></section>'}
function monthKey(d){return String(d||'').slice(0,7)}
function monthlySpendStats(){const expenses=items.filter(x=>x.kind==='expense');if(!expenses.length)return {average:0,months:0};const keys=expenses.map(x=>monthKey(x.occurred_on)).filter(x=>/^\d{4}-\d{2}$/.test(x));if(!keys.length)return {average:0,months:0};const first=keys.sort()[0],last=keys.sort().slice(-1)[0],start=new Date(first+'-01T00:00:00'),end=new Date(last+'-01T00:00:00');const months=(end.getFullYear()-start.getFullYear())*12+end.getMonth()-start.getMonth()+1;const total=expenses.reduce((n,x)=>n+Number(x.amount||0),0);return {average:total/months,months,total}}
function dailySpendStats(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),monthStart=new Date(now.getFullYear(),now.getMonth(),1),yearStart=new Date(now.getFullYear(),0,1);let monthTotal=0,yearTotal=0;items.filter(x=>x.kind==='expense').forEach(x=>{const d=new Date(x.occurred_on);if(!Number.isFinite(d.getTime()))return;const day=new Date(d.getFullYear(),d.getMonth(),d.getDate());if(day>today)return;const amount=Number(x.amount||0);if(day>=monthStart)monthTotal+=amount;if(day>=yearStart)yearTotal+=amount});const monthDays=now.getDate(),yearDays=Math.floor((today-yearStart)/86400000)+1;return {monthTotal,yearTotal,monthDays,yearDays,monthAverage:monthTotal/Math.max(1,monthDays),yearAverage:yearTotal/Math.max(1,yearDays),monthLabel:now.toLocaleString('en-IN',{month:'long',year:'numeric'}),yearLabel:String(now.getFullYear())}}
function yearlyAverageSpendSeries(){const byYear={};items.filter(x=>x.kind==='expense').forEach(x=>{const d=new Date(x.occurred_on);if(!Number.isFinite(d.getTime()))return;const y=d.getFullYear(),m=d.getMonth();if(!byYear[y])byYear[y]={year:y,months:new Set(),total:0};byYear[y].months.add(m);byYear[y].total+=Number(x.amount||0)});return Object.values(byYear).sort((a,b)=>a.year-b.year).map(x=>({month:String(x.year),average:x.total/Math.max(1,x.months.size),total:x.total,months:x.months.size}))}
function monthlyCashSeries(){const map={};items.forEach(x=>{const k=monthKey(x.occurred_on);if(!/^\d{4}-\d{2}$/.test(k))return;if(!map[k])map[k]={month:k,income:0,spend:0};if(x.kind==='income')map[k].income+=Number(x.amount||0);if(x.kind==='expense')map[k].spend+=Number(x.amount||0)});return Object.values(map).sort((a,b)=>a.month.localeCompare(b.month)).slice(-12)}
function parseMoney(v){const n=Number(String(v??'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null}
function historicalCashBalances(){const byDate={};sourceSections.forEach(s=>{(s.tables||[]).forEach(rows=>{if(!rows.length)return;const heads=rows[0].map(v=>String(v).toLowerCase());const ai=heads.findIndex(v=>v==='account'||v==='account / bucket shown');const bi=heads.findIndex(v=>v.includes('latest balance')||v==='displayed amount');if(ai<0||bi<0||!s._date)return;rows.slice(1).forEach(r=>{const label=String(r[ai]||'');if(!label||/total|visible accounts total/i.test(label))return;const value=parseMoney(r[bi]);if(value===null)return;const key=accountKey(label);if(!key)return;byDate[s._date] ||= {};byDate[s._date][key]=value})})});return Object.entries(byDate).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,accounts])=>({date,total:Object.values(accounts).reduce((a,b)=>a+b,0),accounts}))}
function svgLineChart(series,keys,labels,format){if(!series.length)return '<p class="muted">Not enough historical data yet. Add dated transactions or bank-balance snapshots to build this chart.</p>';const w=720,h=230,l=76,r=18,t=18,b=42,vals=series.flatMap(d=>keys.map(k=>Number(d[k]||0))),max=Math.max(1,...vals),min=Math.min(0,...vals),x=i=>l+(series.length===1?(w-l-r)/2:i*(w-l-r)/(series.length-1)),y=v=>t+(max-v)/(max-min||1)*(h-t-b);let grid='';for(let i=0;i<=4;i++){const v=min+(max-min)*i/4,yy=y(v);grid+='<line x1="'+l+'" y1="'+yy+'" x2="'+(w-r)+'" y2="'+yy+'" stroke="#2b3b52" stroke-dasharray="3 5"/><text x="'+(l-9)+'" y="'+(yy+4)+'" text-anchor="end" fill="#b0bfd2" font-size="11">'+esc(format(v))+'</text>'}const paths=keys.map((k,j)=>{const pts=series.map((d,i)=>x(i)+','+y(Number(d[k]||0))).join(' ');const color=j===0?'#78a8ff':'#65ddb2';return '<polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'+series.map((d,i)=>{const label=(d.month||d.date||'Period')+' · '+labels[j],value=format(Number(d[k]||0));return '<g class="chart-point" tabindex="0" role="button" aria-label="'+esc(label+' '+value)+'" data-chart-label="'+esc(label)+'" data-chart-value="'+esc(value)+'"><circle cx="'+x(i)+'" cy="'+y(Number(d[k]||0))+'" r="13" fill="transparent"/><circle cx="'+x(i)+'" cy="'+y(Number(d[k]||0))+'" r="4.5" fill="'+color+'" stroke="#101a2b" stroke-width="2"/></g>'}).join('')}).join('');const ticks=series.map((d,i)=>'<text x="'+x(i)+'" y="'+(h-12)+'" text-anchor="middle" fill="#b0bfd2" font-size="11">'+esc(d.month||d.date.slice(5))+'</text>').join('');return '<div class="chart-interactive"><div class="chart-scroll"><svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Interactive historical chart. Touch or select a data point to see its exact amount.">'+grid+paths+ticks+'</svg></div><div class="chart-tooltip" aria-live="polite" hidden></div></div><div class="chart-legend">'+keys.map((k,i)=>'<span><i style="background:'+(i===0?'#78a8ff':'#65ddb2')+'"></i>'+esc(labels[i])+'</span>').join('')+'</div>'}
function sectionMetric(sectionPattern,rowPattern,valueIndex=1){for(const s of sourceSections){if(!sectionPattern.test(String(s.heading||'')))continue;for(const rows of (s.tables||[])){if(!rows.length)continue;for(const row of rows.slice(1)){if(rowPattern.test(String(row[0]||''))){const v=parseMoney(row[valueIndex]);if(v!==null)return v}}}}return 0}
function latestCashAccountBalances(){const accounts={};historicalCashBalances().forEach(day=>Object.entries(day.accounts).forEach(([key,value])=>{accounts[key]=value}));delete accounts['Fixed deposits'];return accounts}
function wealthPosition(){const latestAccounts=latestCashAccountBalances();delete latestAccounts.Roarbank;const bank=Object.values(latestAccounts).reduce((n,v)=>n+Number(v||0),0);const roarbank=sectionMetric(/Roarbank credit line and savings/i,/^Savings account$/i);const atom=latestAccounts.Atom??sectionMetric(/Other banking \/ savings cards/i,/^Atom savings$/i);const fd=sectionMetric(/Other banking \/ savings cards/i,/^Fixed deposits$/i);const pf=sectionMetric(/EPF \/ EPS — Combined summary/i,/^Total$/i,3);const equity=sectionMetric(/Angel One equity overview/i,/^Current equity value$/i);const mutualFunds=sectionMetric(/Angel One mutual funds/i,/^Portfolio total$/i);const gold=sectionMetric(/precious metals/i,/^Paytm Gold$/i);const silver=sectionMetric(/precious metals/i,/^Paytm Silver$/i);const usStocks=sectionMetric(/INDmoney US Stocks/i,/^Current value$/i);const casa=bank+roarbank;const investments=equity+mutualFunds+gold+silver+usStocks+fd+pf;const recordedLiabilities=items.filter(x=>x.kind==='liability').reduce((n,x)=>n+Number(x.amount||0),0);const hasHdfcLedger=items.some(x=>x.kind==='liability'&&/hdfc/i.test(String(x.account||'')));const otherCardUsage=hasHdfcLedger?0:Math.max(0,sectionMetric(/HDFC Swiggy Orange credit card/i,/^Limit utilized$/i));const liabilities=recordedLiabilities+otherCardUsage;return {bank,latestAccounts,roarbank,atom,fd,pf,casa,equity,mutualFunds,gold,silver,usStocks,investments,liabilities,total:casa+investments-liabilities}}
let wealthExpanded=null,showCategorySpend=false;
function wealthDetailRows(pattern){const out=[];sourceSections.filter(s=>pattern.test(String(s.heading||''))).forEach(s=>(s.tables||[]).forEach(rows=>{if(!rows.length)return;const headers=rows[0]||[];rows.slice(1).forEach(row=>{if(!row[0])return;const amount=parseMoney(row[1]);out.push({label:String(row[0]),amount, date:s._date||''})})}));return out}
function investmentBreakdownHtml(w){const equityInvested=sectionMetric(/Angel One equity overview/i,/^Invested value$/i),equityPnl=sectionMetric(/Angel One equity overview/i,/^Overall unrealised P&L$/i);const equityDay=sectionMetric(/Angel One equity overview/i,/^Today's gain$/i);const equitySection=sourceSections.find(x=>/Angel One equity holdings/i.test(String(x.heading||'')));const equityRows=equitySection?(equitySection.tables||[]).flatMap(t=>{const h=(t[0]||[]).map(v=>String(v).toLowerCase());const idx={qty:h.findIndex(v=>v==='qty'||v.includes('quantity')),avg:h.findIndex(v=>v.includes('avg buy')),ltp:h.findIndex(v=>v.includes('ltp')),pnl:h.findIndex(v=>v.includes('p&l'))};return t.slice(1).filter(r=>r[0]&&!/total/i.test(String(r[0]))).map(r=>({name:String(r[0]),qty:String(r[idx.qty]||''),avg:String(r[idx.avg]||''),ltp:String(r[idx.ltp]||''),pnl:String(r[idx.pnl]||'')})).filter(r=>r.qty)}):[];const equityHoldingsHtml=equityRows.length?'<details class="investment-holdings-toggle"><summary>Show '+equityRows.length+' stock / ETF details</summary><div class="investment-holdings investment-holdings-detailed">'+equityRows.map(r=>'<div class="investment-stock-row"><div class="investment-stock-title"><b>'+esc(r.name)+'</b><span>Qty: '+esc(r.qty)+'</span></div><div class="investment-stock-prices"><span><small>Avg buy</small><b>'+esc(r.avg||'—')+'</b></span><span><small>Current LTP</small><b>'+esc(r.ltp||'—')+'</b></span><span><small>P&L</small><b class="'+(/\(|−|-/.test(r.pnl)?'negative':/^[+]/.test(r.pnl)?'positive':'neutral')+'">'+esc(r.pnl||'—')+'</b></span></div></div>').join('')+'</div></details>':'<p class="investment-note">Share quantities were not present in the latest saved source.</p>';const dematSection=sourceSections.find(x=>/Angel One demat holdings/i.test(String(x.heading||'')));const dematQty={};if(dematSection)(dematSection.tables||[]).forEach(t=>t.slice(1).forEach(r=>{if(r[0]&&r[1]&&!/total/i.test(String(r[0])))dematQty[String(r[0]).toLowerCase().trim()]=String(r[1])}));const mfInvested=sectionMetric(/Angel One mutual funds/i,/^Invested value$/i);const mfSection=sourceSections.find(x=>/Angel One mutual funds/i.test(String(x.heading||'')));const mfRows=mfSection?(mfSection.tables||[]).flatMap(t=>t.slice(1).filter(r=>r[0]&&!/portfolio total|invested value/i.test(String(r[0]))).map(r=>({name:String(r[0]),value:parseMoney(r[1])})).filter(r=>r.value!==null)):[];const metalSections=[...sourceSections].sort((a,b)=>String(b._date||'').localeCompare(String(a._date||'')));const quantityRows=metalSections.flatMap(section=>(section.tables||[]).flatMap(t=>{const h=(t[0]||[]).map(v=>String(v).toLowerCase());const qi=h.findIndex(v=>v.includes('quantity'));return qi<0?[]:t.slice(1).filter(r=>r[0]).map(r=>({name:String(r[0]),quantity:String(r[qi]||''),date:String(section._date||'')}))}));const actualGold=quantityRows.find(r=>/paytm gold/i.test(r.name)&&!(/coin/i.test(r.name)));const silverQuantity=quantityRows.find(r=>/paytm silver/i.test(r.name));const coinSection=metalSections.find(x=>/paytm gold coins/i.test(String(x.heading||'')));const coinRow=(coinSection?.tables||[]).flatMap(t=>t.slice(1)).find(r=>/gold coins/i.test(String(r[0]||'')));const goldCoinQuantity=coinRow?String(coinRow[1]||''):'';const usRows=positions.filter(p=>p.category==='INVESTMENT'&&/INDmoney/i.test(String(p.platform_name||'')));return '<div class="investment-categories"><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">▤</span><div><b>Fixed deposits</b><small>Bank deposits · moved from Cash & deposits</small></div><strong>'+money(w.fd)+'</strong></div></section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">◎</span><div><b>EPF / EPS · Provident fund</b><small>Combined two-employer passbook balances · displayed date 31 Mar 2027</small></div><strong>'+money(w.pf)+'</strong></div><p class="investment-note">EPF and EPS are shown together as reported in the passbooks. EPS is a pension component, not ordinary withdrawable EPF. The passbook closing date is future-dated relative to the 9 Nov 2026 snapshot, so treat ₹93,726 as the displayed figure, not a verified current valuation.</p></section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">↗</span><div><b>Equity · Angel One</b><small>Direct stocks and ETFs</small></div><strong>'+money(w.equity)+'</strong></div><div class="investment-category-metrics"><div><small>Invested</small><b>'+money(equityInvested)+'</b></div><div><small>Unrealised P&L</small><b class="'+(equityPnl<0?'negative':'positive')+'">'+money(equityPnl)+'</b></div><div><small>Today’s gain</small><b class="'+(equityDay<0?'negative':'positive')+'">'+money(equityDay)+'</b></div></div>'+equityHoldingsHtml+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">$</span><div><b>INDmoney · US Stocks</b><small>Personal portfolio · US equities and ETF</small></div><strong>'+money(w.usStocks)+'</strong></div>'+(usRows.length?'<details class="investment-holdings-toggle"><summary>Show '+usRows.length+' US stock / ETF holdings</summary><div class="investment-holdings">'+usRows.map(r=>'<div class="investment-us-row"><span><b>'+esc(r.name)+'</b><small>'+esc(r.ticker||'')+' · '+esc(r.record_type==='ETF'?'ETF':'US equity')+' · Qty: '+esc(r.quantity??'—')+'</small></span><b>'+new Intl.NumberFormat('en-US',{style:'currency',currency:String(r.currency||'USD'),maximumFractionDigits:2}).format(Number(r.current_value||0))+'</b></div>').join('')+'</div></details>':'')+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">◫</span><div><b>Mutual funds</b><small>Angel One fund portfolio</small></div><strong>'+money(w.mutualFunds)+'</strong></div><div class="investment-category-metrics"><div><small>Invested</small><b>'+money(mfInvested)+'</b></div><div><small>Gain / return</small><b class="positive">'+money(w.mutualFunds-mfInvested)+'</b></div></div>'+(mfRows.length?'<details class="investment-holdings-toggle"><summary>Show '+mfRows.length+' mutual fund holdings</summary><div class="investment-holdings">'+mfRows.map(r=>{const q=dematQty[r.name.toLowerCase().trim()];return '<div><span>'+esc(r.name)+(q?'<small>Last recorded units (31 Oct): '+esc(q)+'</small>':'<small>Units not captured in latest snapshot</small>')+'</span><b>'+money(r.value)+'</b></div>'}).join('')+'</div></details>':'')+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">◆</span><div><b>Gold</b><small>Paytm Gold</small></div><strong>'+money(w.gold)+'</strong></div>'+(actualGold?'<p class="investment-note">Actual digital gold · '+esc(actualGold.quantity)+' ('+esc(actualGold.date)+')</p>':'<p class="investment-note">Actual gold quantity not available in saved source.</p>')+(goldCoinQuantity?'<p class="investment-note">Paytm reward coins · '+esc(goldCoinQuantity)+' (not included in gold asset value)</p>':'')+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">◇</span><div><b>Silver</b><small>Paytm Silver</small></div><strong>'+money(w.silver)+'</strong></div>'+(silverQuantity?'<p class="investment-note">Actual digital silver · '+esc(silverQuantity.quantity)+' ('+esc(silverQuantity.date)+')</p>':'<p class="investment-note">Actual silver quantity not available in saved source.</p>')+'</section></div>'}
function wealthExpandedHtml(key,w){let rows=[];if(key==='casa'){Object.entries(w.latestAccounts||{}).forEach(([name,value])=>rows.push({label:name,amount:value}));if(w.roarbank>0)rows.push({label:'Roarbank savings account',amount:w.roarbank});}if(key==='liabilities')items.filter(x=>x.kind==='liability').forEach(x=>rows.push({label:(x.account||x.category||'Credit usage')+' · '+(x.description||''),amount:Number(x.amount||0),date:String(x.occurred_on||'').slice(0,10)}));const total=key==='casa'?w.casa:key==='investments'?w.investments:w.liabilities;const body=key==='investments'?investmentBreakdownHtml(w):(rows.length?'<div class="wealth-detail-list">'+rows.map(r=>'<div class="wealth-detail-row"><span>'+esc(r.label)+(r.date?'<small>'+esc(r.date)+'</small>':'')+'</span><b>'+money(r.amount||0)+'</b></div>').join('')+'</div>':'<p class="muted">No detailed records available in the latest saved data.</p>');return '<div class="wealth-expanded" id="wealth-expanded-'+key+'"><div class="wealth-expanded-head"><b>'+({casa:'Cash & deposits breakdown',investments:'Investment breakdown',liabilities:'Outstanding credit usage'}[key])+'</b><strong>'+money(total)+'</strong></div>'+body+'</div>'}
function renderTopWealth(){const el=$('stats');if(!el)return;const w=wealthPosition();const cards=[['casa','⌂','CASA',w.casa,'Bank · Atom · Roarbank','casa-icon'],['investments','↗','INVESTMENTS',w.investments,'Equity · MF · Metals · FD · PF','invest-icon'],['liabilities','−','LIABILITIES',w.liabilities,'Credit used','liability-icon']];el.innerHTML='<div class="wealth-hero"><div><div class="eyebrow">TOTAL BALANCE AVAILABLE</div><div class="wealth-total">'+money(w.total)+'</div><div class="wealth-equation">CASA + Investments − Liabilities</div></div><div class="wealth-hero-mark">₹</div></div><div class="wealth-kpis">'+cards.map(c=>'<button type="button" class="wealth-kpi '+(c[0]==='liabilities'?'liability-kpi':'')+'" data-wealth-expand="'+c[0]+'" aria-expanded="'+(wealthExpanded===c[0]?'true':'false')+'" aria-controls="wealth-expanded-'+c[0]+'"><span class="kpi-top"><i class="kpi-icon '+c[5]+'">'+c[1]+'</i><small>'+c[2]+'</small><i class="wealth-chevron">'+(wealthExpanded===c[0]?'−':'+')+'</i></span><strong>'+money(c[3])+'</strong><span>'+c[4]+' · Tap for details</span></button>').join('')+'</div>'+(wealthExpanded?wealthExpandedHtml(wealthExpanded,w):'');el.querySelectorAll('[data-wealth-expand]').forEach(b=>b.addEventListener('click',()=>{wealthExpanded=wealthExpanded===b.dataset.wealthExpand?null:b.dataset.wealthExpand;renderTopWealth()}))}

function categorySpendHtml(){const expenses=items.filter(x=>x.kind==='expense');const totals={};expenses.forEach(x=>{const k=String(x.category||'Uncategorised').trim()||'Uncategorised';totals[k]=(totals[k]||0)+Number(x.amount||0)});const rows=Object.entries(totals).sort((a,b)=>b[1]-a[1]);const total=rows.reduce((n,r)=>n+r[1],0);const months=monthlySpendStats().months||1;const overallAverage=total/months;return '<section class="chart-card category-spend" id="categorySpend"><div class="chart-head"><div><h4>Category spend vs monthly average</h4><p>Each category shows total spent and its monthly average across '+months+' recorded calendar month(s)</p></div><button type="button" class="ghost spend-close" data-spend-close>Close</button></div>'+(rows.length?'<div class="category-spend-benchmark"><span>Overall average monthly spend</span><b>'+money(overallAverage)+'</b></div><div class="category-spend-list">'+rows.map(([name,value])=>{const avg=value/months;const share=total?value/total*100:0;const relative=overallAverage?avg/overallAverage*100:0;return '<div class="category-spend-row"><div class="category-spend-label"><b>'+esc(name)+'</b><strong>'+money(value)+'</strong></div><div class="category-spend-compare"><span>Monthly avg <b>'+money(avg)+'</b></span><span>'+relative.toFixed(1)+'% of overall avg</span></div><div class="category-spend-track"><i style="width:'+Math.max(0,Math.min(100,relative))+'%"></i></div><small>'+share.toFixed(1)+'% of total expenses · '+money(avg)+' per month</small></div>'}).join('')+'</div><div class="category-spend-total"><span>Total expenses · monthly average</span><b>'+money(total)+' · '+money(overallAverage)+'/mo</b></div>':'<p class="muted">No expense categories have been recorded yet.</p>')+'</section>'}
function monthCategorySpendHtml(){const now=new Date(),key=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0'),expenses=items.filter(x=>x.kind==='expense'&&monthKey(x.occurred_on)===key),totals={};expenses.forEach(x=>{const k=String(x.category||'Uncategorised').trim()||'Uncategorised';totals[k]=(totals[k]||0)+Number(x.amount||0)});const rows=Object.entries(totals).sort((a,b)=>b[1]-a[1]),total=rows.reduce((n,r)=>n+r[1],0),days=now.getDate(),allMonths=monthlySpendStats().months||1;return '<section class="chart-card category-spend" id="monthCategorySpend"><div class="chart-head"><div><h4>This month: category spending</h4><p>'+esc(now.toLocaleString('en-IN',{month:'long',year:'numeric'}))+' · actual spend versus averages</p></div><button type="button" class="ghost spend-close" data-spend-close>Close</button></div>'+(rows.length?'<div class="category-spend-benchmark"><span>This month total · daily average</span><b>'+money(total)+' · '+money(total/Math.max(1,days))+'/day</b></div><div class="category-spend-list">'+rows.map(([name,value])=>{const daily=value/Math.max(1,days),share=total?value/total*100:0;return '<div class="category-spend-row"><div class="category-spend-label"><b>'+esc(name)+'</b><strong>'+money(value)+'</strong></div><div class="category-spend-compare"><span>Daily avg <b>'+money(daily)+'</b></span><span>Month-end run-rate '+money(daily*new Date(now.getFullYear(),now.getMonth()+1,0).getDate())+'</span></div><div class="category-spend-track"><i style="width:'+Math.max(0,Math.min(100,share))+'%"></i></div><small>'+share.toFixed(1)+'% of this month · historical monthly average '+money(value/allMonths)+'</small></div>'}).join('')+'</div><div class="category-spend-total"><span>This month · daily average</span><b>'+money(total)+' · '+money(total/Math.max(1,days))+'/day</b></div>':'<p class="muted">No expense categories have been recorded this month.</p>')+'</section>'}
function analyticsHtml(){const stats=monthlySpendStats(),daily=dailySpendStats(),cash=monthlyCashSeries(),yearly=yearlyAverageSpendSeries(),balances=historicalCashBalances();return '<div class="analytics-grid"><article class="mini-card spend-click-card" data-month-spend-breakdown role="button" tabindex="0" aria-expanded="'+(showMonthSpend?'true':'false')+'"><small>DAILY AVERAGE · THIS MONTH</small><strong>'+money(daily.monthAverage)+'</strong><span>'+esc(daily.monthLabel)+' · '+money(daily.monthTotal)+' spent over '+daily.monthDays+' elapsed days</span></article><article class="mini-card"><small>DAILY AVERAGE · THIS YEAR</small><strong>'+money(daily.yearAverage)+'</strong><span>'+daily.yearLabel+' year-to-date · '+money(daily.yearTotal)+' spent over '+daily.yearDays+' elapsed days</span></article><article class="mini-card spend-click-card" data-spend-breakdown role="button" tabindex="0" aria-expanded="'+(showCategorySpend?'true':'false')+'"><small>AVERAGE MONTHLY SPEND</small><strong>'+money(stats.average)+'</strong><span>Based on '+stats.months+' calendar month(s) · expenses only · Tap for category breakdown</span></article><article class="mini-card"><small>HISTORICAL EXPENSES</small><strong>'+money(stats.total||0)+'</strong><span>Transfer and investment movements excluded</span></article></div>'+(showMonthSpend?monthCategorySpendHtml():'')+(showCategorySpend?categorySpendHtml():'')+'<section class="chart-card"><div class="chart-head"><div><h4>Cash flow trend</h4><p>Monthly income versus spending · latest 12 months</p></div></div>'+svgLineChart(cash,['income','spend'],['Money in','Spending'],v=>money(v))+'</section><section class="chart-card"><div class="chart-head"><div><h4>Average monthly spend by year</h4><p>Year-wise average · expenses only · months with recorded expenses</p></div></div>'+svgLineChart(yearly,['average'],['Average monthly spend'],v=>money(v))+(yearly.length?'<p class="chart-foot">'+yearly.map(x=>esc(x.month)+': '+money(x.average)+' / month · '+money(x.total)+' total').join(' &nbsp; | &nbsp; ')+'</p>':'')+'</section><section class="chart-card"><div class="chart-head"><div><h4>Bank balance history</h4><p>Historical cash balances from saved account snapshots</p></div></div>'+svgLineChart(balances.map(d=>({month:d.date.slice(5),total:d.total})),['total'],['Total bank cash'],v=>money(v))+(balances.length?'<p class="chart-foot">Latest recorded balance: '+money(balances[balances.length-1].total)+' · '+balances[balances.length-1].date+'</p>':'')+'</section>'}
async function loadSnapshot(){try{const d=await api('/api/snapshot');sourceSections=[];(d.snapshots||[]).forEach(snap=>{let p=snap.payload;if(typeof p==='string'){try{p=JSON.parse(p)}catch{p={}}}(p.sections||[]).forEach(s=>sourceSections.push({...s,_source:snap.source_name,_date:String(snap.snapshot_date||'').slice(0,10)}))});$('snapshotStatus').textContent=sourceSections.length+' source sections · '+(d.snapshots||[]).length+' saved snapshots';$('sourceCount').textContent=sourceSections.length+' imported sections';renderTopWealth();renderView(activeView)}catch(e){$('snapshotStatus').textContent='Could not load source data';$('sourceCount').textContent=e.message}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function isInvestmentRecord(s){const text=(String(s.heading||'')+' '+(s.tables||[]).flat().flat().join(' ')+' '+(s.notes||[]).join(' ')).toLowerCase();return /fixed deposit|epf\s*\/\s*eps|employee epf|eps pension|investment|portfolio|mutual fund|stocks|equity|demat|angel one|zerodha/.test(text)}
function isBankBalanceSection(s){const h=String(s.heading||'').toLowerCase();const headers=(s.tables||[]).flatMap(t=>t[0]||[]).map(v=>String(v).toLowerCase());return /bank & cash accounts|latest bank balances|latest balance snapshot|bank balance snapshot|account balances|roarbank credit line and savings/.test(h)||((headers.includes('account')||headers.includes('account / bucket shown'))&&headers.some(v=>v.includes('latest balance')||v==='displayed amount'))}
function bankName(s){const x=String(s.heading||'')+' '+(s.tables||[]).flat().flat().join(' ');const banks=[['Bank of India',/\bboi\b|bank of india/i],['HDFC Bank',/hdfc/i],['State Bank of India',/\bsbi\b|state bank of india/i],['Slice',/slice/i],['Roarbank',/roarbank|roar bank/i],['Other bank',/bank|account/i]];return (banks.find(b=>b[1].test(x))||banks[banks.length-1])[0]}
function groupFor(s){return isBankBalanceSection(s)?'banks':'other'}
const views=[['overview','Overview'],['banks','Bank Balances'],['investments','Investments'],['stock-advisor','Stock Advisor'],['angel-one','Angel One'],['other','Other Records'],['transactions','Transactions'],['alerts','Alerts'],['subscriptions','Active Subscriptions & Mandates'],['more','More']];
function cleanHeading(s){return String(s.heading||'').replace(/^\d{1,2}\s+November\s+2026\s*[—–-]\s*/i,'').replace(/^Latest balance snapshot\s*[—–-]\s*/i,'').replace(/^\d+\\.\s*/,'');}
function sectionContent(s){const tables=(s.tables||[]).map(rows=>'<div class="snapshot-table-wrap"><table class="snapshot-table"><tbody>'+rows.map((r,ri)=>'<tr>'+r.map(cell=>ri===0?'<th>'+esc(cell)+'</th>':'<td>'+esc(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('');const notes=(s.notes||[]).map(n=>'<li>'+esc(n)+'</li>').join('');return '<div class="source-meta">Source: '+esc(s._source||'HTML source')+'</div>'+tables+(notes?'<ul class="snapshot-notes">'+notes+'</ul>':'')}
function sectionHtml(s,i){return '<details class="snapshot-section" '+(i<2?'open':'')+'><summary>'+esc(cleanHeading(s))+'</summary>'+sectionContent(s)+'</details>'}
function mergedOtherHtml(sections){return '<div class="merged-records">'+sections.map((s,i)=>'<section class="merged-record"><h4>'+esc(s.heading)+'</h4>'+sectionContent(s)+'</section>').join('')+'</div>'}
function accountKey(label){const x=String(label||'').toLowerCase().replace(/[•·]/g,' ').replace(/\s+/g,' ').trim();const sections=accountingTemplate?.sections||[];const reward=sections.find(s=>s.key==='rewards');if((reward?.assets||[]).some(a=>x.includes(String(a).toLowerCase())))return null;const aliases=accountingTemplate?.accountAliases||{};for(const [canonical,names] of Object.entries(aliases)){if([canonical,...names].some(a=>x.includes(String(a).toLowerCase())))return canonical}if(/\bmonies\b|reward coins|reward points|cashback coins/.test(x))return null;return String(label||'Other account').trim();}
function accountRecords(key){return sourceSections.filter(s=>{const text=(String(s.heading||'')+' '+(s.tables||[]).flat().flat().join(' ')+' '+(s.notes||[]).join(' ')).toLowerCase();const k=key.toLowerCase();return k==='slice'?text.includes('slice'):k==='bank of india'?text.includes('bank of india')||text.includes('boi'):k==='hdfc bank'?text.includes('hdfc'):k==='roarbank'?text.includes('roarbank')||text.includes('roar bank'):k==='atom'?text.includes('atom'):k==='fixed deposits'?text.includes('fixed deposit'):text.includes(k)});}
function openBank(key){activeBank=key;renderView('bank-detail');}
function bankCards(sections){const seen=new Set();const cards=[];sections.forEach(s=>{let rendered=false;(s.tables||[]).forEach(rows=>{if(!rows.length)return;const headers=rows[0].map(v=>String(v).toLowerCase());const ai=headers.findIndex(v=>v==='account'||v==='account / bucket shown');const bi=headers.findIndex(v=>v.includes('latest balance')||v==='displayed amount');if(ai<0||bi<0){if(/roarbank credit line and savings/i.test(String(s.heading||''))){const savings=rows.slice(1).find(r=>/^savings account$/i.test(String(r[0]||'')));if(savings&&savings[1]&&!seen.has('Roarbank')){seen.add('Roarbank');cards.push('<button type="button" class="bank-balance-card" data-bank="Roarbank"><div class="bank-card-head"><h4>Roarbank</h4><span>Savings account</span></div><div class="bank-metrics"><div class="bank-metric"><small>Latest balance</small><strong>'+esc(savings[1])+'</strong></div></div><span class="bank-open">View account details →</span><div class="source-meta">Updated '+esc(s._date||'')+'</div></button>')}}return}rows.slice(1).forEach(row=>{if(!row[ai])return;const label=String(row[ai]);if(/fixed\\s*deposits?/i.test(label))return;const bank=accountKey(label);if(/total|visible accounts total/i.test(label)||seen.has(bank))return;seen.add(bank);const rest=row.map((v,k)=>'<div class="bank-metric"><small>'+esc(rows[0][k])+'</small><strong>'+esc(v)+'</strong></div>').join('');cards.push('<button type="button" class="bank-balance-card" data-bank="'+esc(bank)+'"><div class="bank-card-head"><h4>'+esc(bank)+'</h4><span>'+esc(label)+'</span></div><div class="bank-metrics">'+rest+'</div><span class="bank-open">View account details →</span><div class="source-meta">Updated '+esc(s._date||'')+'</div></button>')});rendered=true});if(!rendered)cards.push('<section class="merged-record"><h4>'+esc(s.heading)+'</h4>'+sectionContent(s)+'</section>')});const order=['Slice','HDFC Bank','Bank of India','Roarbank','Atom','Fixed deposits'];cards.sort((a,b)=>{const get=x=>{const m=x.match(/data-bank=\"([^\"]+)/);return m?m[1]:''};const ai=order.indexOf(get(a)),bi=order.indexOf(get(b));return (ai<0?99:ai)-(bi<0?99:bi)});return cards.join('')}
function angelOneHtml(){return '<section class="chart-card"><div class="chart-head"><div><h4>Angel One · SmartAPI</h4><p>Secure, read-only sync of holdings, funds and positions</p></div><span class="pill">READ ONLY</span></div><p class="muted">Broker credentials stay on the server in Vercel environment variables. They are never stored in browser code or displayed here.</p><button type="button" class="primary" data-angel-refresh>Connect / Refresh Angel One</button><div id="angelResult" class="muted" style="margin-top:14px">Tap Connect to check the SmartAPI connection.</div></section>'}
async function loadAngelOne(){const box=$('angelResult');if(!box)return;box.textContent='Connecting securely to Angel One…';try{const d=await api('/api/angel');if(!d.connected){box.innerHTML=d.setupRequired?'<b>Setup required</b><p>Configure these Vercel environment variables: '+(d.missing||[]).map(esc).join(', ')+'</p><p class="muted">Then redeploy and try again. Do not share your PIN, TOTP seed or API key in chat.</p>':'<p class="error">'+esc(d.error||'Connection unavailable')+'</p>';return}const rows=Array.isArray(d.holdings)?d.holdings:[];const fmt=v=>v==null?'—':esc(String(v));const keys=rows.length?Object.keys(rows[0]):[];box.innerHTML='<div class="analytics-grid"><article class="mini-card"><small>HOLDINGS</small><strong>'+rows.length+'</strong></article><article class="mini-card"><small>POSITIONS</small><strong>'+(Array.isArray(d.positions)?d.positions.length:0)+'</strong></article><article class="mini-card"><small>SYNCED</small><strong>'+esc(new Date(d.fetchedAt).toLocaleTimeString())+'</strong></article></div>'+(rows.length?'<div class="table-wrap"><table><thead><tr>'+keys.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+keys.map(k=>'<td>'+fmt(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<p class="muted">No holdings returned by Angel One.</p>')+'<details><summary>Funds / RMS and positions (raw response)</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(JSON.stringify({rms:d.rms,positions:d.positions},null,2))+'</pre></details>'}catch(e){box.innerHTML='<p class="error">'+esc(e.message)+'</p>'}}
function stockAdvisorHtml(){return '<section class="stock-advisor-intro"><div class="eyebrow">INDIAN EQUITY RESEARCH</div><h3>Stock Advisor</h3><p>Research-backed BUY, HOLD and SELL watchlists using technical trends, business fundamentals and company news.</p><div class="stock-advisor-tags"><span>Technical analysis</span><span>Fundamental quality</span><span>Exa news research</span><span>NSE / BSE</span></div></section><div class="stock-advisor-grid"><article class="stock-signal-card buy"><div class="stock-signal-head"><b>BUY</b><span>Entry candidates</span></div><p>No verified BUY signals yet.</p></article><article class="stock-signal-card hold"><div class="stock-signal-head"><b>HOLD</b><span>Existing holdings</span></div><p>Holdings analysis will appear here after market data is connected.</p></article><article class="stock-signal-card sell"><div class="stock-signal-head"><b>SELL</b><span>Exit candidates</span></div><p>No verified SELL signals yet.</p></article></div><section class="chart-card stock-advisor-method"><h4>How recommendations will be evaluated</h4><div class="stock-method-grid"><div><b>Technical</b><p>Trend, RSI, MACD, moving averages, volume and support / resistance.</p></div><div><b>Fundamental</b><p>Revenue and profit growth, ROE / ROCE, debt, cash flow, valuation and sector quality.</p></div><div><b>Research</b><p>Exa-sourced company news with source links, publication dates and relevance to the investment thesis.</p></div></div><p class="stock-data-note">Live recommendations are not enabled yet. The Indian market-price feed and reliable fundamental data must be connected and validated first. No prices or BUY / SELL signals are fabricated.</p></section>'}
function moreHubHtml(){const banks=sourceSections.filter(isBankBalanceSection).length;const other=sourceSections.filter(s=>!isBankBalanceSection(s)&&!isInvestmentRecord(s)).length;const due=plannedBills.filter(b=>b.status==='planned').length;const rows=[{group:'YOUR MONEY',items:[['banks','Bank accounts','Balances, account snapshots and details','▣',banks],['investments','Investments','Stocks, mutual funds and metals','↗',null],['other','Other records','Imported statements and saved records','◫',other]]},{group:'ACTIVITY & REMINDERS',items:[['transactions','Transactions','Income, spending and transfers','≡',items.length],['alerts','Alerts & bills','Upcoming payments and reminders','!',due],['subscriptions','Subscriptions & mandates','Recurring payments and authorisations','⟳',subscriptions.length]]},{group:'TOOLS',items:[['stock-advisor','Stock Advisor','Research and portfolio signals for Indian stocks','⌁',null],['overview','Financial overview','Charts, cash flow and account summary','⌂',null]]}];return '<section class="more-hub"><div class="more-welcome"><div class="eyebrow">QUICK ACCESS</div><h3>Everything in one place</h3><p>Choose what you want to review. Your saved financial records stay unchanged.</p></div>'+rows.map(g=>'<section class="more-group"><h4>'+g.group+'</h4><div class="more-list">'+g.items.map(x=>'<button type="button" class="more-link" data-view="'+x[0]+'"><span class="more-link-icon">'+x[3]+'</span><span class="more-link-copy"><b>'+x[1]+'</b><small>'+x[2]+'</small></span>'+(x[4]===null?'':'<span class="more-link-count">'+x[4]+'</span>')+'<span class="more-link-arrow">›</span></button>').join('')+'</div></section>').join('')+'<div class="more-footnote"><span>●</span> '+sourceSections.length+' imported sections · '+items.length+' ledger entries · data preserved</div></section>'}
function fixedDepositsHtml(){const fds=positions.filter(p=>p.category==='INVESTMENT'&&p.record_type==='FIXED_DEPOSIT'&&/Angel One/i.test(String(p.platform_name||'')));const total=fds.reduce((n,p)=>n+Number(p.current_value||0),0);return '<section class="chart-card"><div class="chart-head"><div><h4>Angel One · Fixed Deposits</h4><p>FDs held through Angel One · saved in your investment records</p></div><span class="pill">'+fds.length+' FDs</span></div><form id="fdForm" class="formgrid"><label>FD name<input name="name" maxlength="120" required placeholder="e.g. Suryoday Small Finance Bank FD"></label><label>Issuing bank (optional)<input name="institution_name" maxlength="120" placeholder="Bank / NBFC"></label><label>Invested amount (₹)<input name="invested_value" type="number" min="0.01" step="0.01" required></label><label>Current value (₹)<input name="current_value" type="number" min="0.01" step="0.01" required></label><label>Interest rate (% p.a.)<input name="interest_rate" type="number" min="0" max="100" step="0.01" placeholder="Optional"></label><label>Maturity date<input name="maturity_date" type="date"></label><button class="primary" type="submit">＋ Add Angel One FD</button><p id="fdMsg" class="message"></p></form><div class="wealth-detail-row"><b>Total current value</b><strong>'+money(total)+'</strong></div>'+(fds.length?'<div class="wealth-detail-list">'+fds.map(p=>{const m=p.metadata||{};return '<div class="wealth-detail-row"><span><b>'+esc(p.name)+'</b><small>'+esc(p.institution_name||'Issuer not specified')+' · Angel One'+(m.interest_rate!=null?' · '+esc(m.interest_rate)+'% p.a.':'')+(m.maturity_date?' · Matures '+esc(m.maturity_date):'')+'</small><small>Invested '+money(p.invested_value||0)+'</small></span><b>'+money(p.current_value||0)+'</b></div>'}).join('')+'</div>':'<p class="muted">No Angel One FDs added yet. Add your first FD above.</p>')+'</section>'}
function renderView(view){activeView=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('sourceNav').classList.remove('more-open');const target=$('viewContent');if(!target)return;const banks=sourceSections.filter(isBankBalanceSection);const other=sourceSections.filter(s=>!isBankBalanceSection(s)&&!isInvestmentRecord(s));$('viewTitle').textContent=(views.find(v=>v[0]===view)||views[0])[1];const viewEyebrow=$('viewTitle').previousElementSibling;if(viewEyebrow)viewEyebrow.textContent=view==='more'?'QUICK ACCESS':'SOURCE DATA · PRESERVED';if(view==='more'){target.innerHTML=moreHubHtml()}else if(view==='alerts'){target.innerHTML=plannedBillsHtml()}else if(view==='subscriptions'){target.innerHTML=subscriptionsHtml()}else if(view==='stock-advisor'){target.innerHTML=stockAdvisorHtml()}else if(view==='angel-one'){target.innerHTML=angelOneHtml()}else if(view==='bank-detail'){const records=accountRecords(activeBank);target.innerHTML='<button type="button" class="ghost" id="backToBanks">← Back to accounts</button><h3 class="group-title">'+esc(activeBank)+' · Account details</h3>'+(records.length?records.map(s=>'<section class="merged-record"><h4>'+esc(cleanHeading(s))+'</h4>'+sectionContent(s)+'<div class="source-meta">Source: '+esc(s._source||'Saved snapshot')+' · Updated '+esc(s._date||'')+'</div></section>').join(''):'<p class="muted">No saved details found for this account yet.</p>')}else if(view==='overview'){target.innerHTML=alertsBannerHtml()+analyticsHtml()+'<div class="overview-grid"><article class="mini-card"><small>CASH BALANCE</small><strong>'+money((historicalCashBalances().slice(-1)[0]||{}).total||0)+'</strong><span>Latest saved bank balance snapshot</span></article><article class="mini-card"><small>LIABILITIES</small><strong>'+money(items.filter(x=>x.kind==='liability').reduce((n,x)=>n+Number(x.amount||0),0))+'</strong><span>Recorded liability entries</span></article><article class="mini-card"><small>BANK ACCOUNTS</small><strong>'+banks.length+'</strong></article><article class="mini-card"><small>OTHER RECORDS</small><strong>'+other.length+'</strong></article><article class="mini-card"><small>LIVE TRANSACTIONS</small><strong>'+items.length+'</strong></article></div><p class="muted">Open Banks to view account balances and details.</p>'}else if(view==='banks'){target.innerHTML=banks.length?bankCards(banks):'<p class="muted">No bank balance records found.</p>'}else if(view==='other'){target.innerHTML=other.length?mergedOtherHtml(other):'<p class="muted">No other financial records found.</p>'}else if(view==='investments'){const invested=items.filter(x=>x.kind==='investment').sort((a,b)=>String(b.occurred_on).localeCompare(String(a.occurred_on)));const fdRows=positions.filter(p=>p.category==='INVESTMENT'&&p.record_type==='FIXED_DEPOSIT');const fdTotal=fdRows.reduce((n,p)=>n+Number(p.current_value||0),0);const total=invested.reduce((n,x)=>n+Number(x.amount||0),0)+fdTotal;const records=sourceSections.filter(isInvestmentRecord);target.innerHTML='<div class="analytics-grid"><article class="mini-card"><small>RECORDED INVESTMENTS</small><strong>'+invested.length+'</strong><span>Investment entries in your ledger</span></article><article class="mini-card"><small>TOTAL INVESTED</small><strong>'+money(total)+'</strong><span>Sum of recorded investment entries only</span></article></div><h3 class="group-title">Investment activity</h3>'+(invested.length?'<div class="entries">'+invested.map(x=>'<div class="entry"><div><b>'+esc(x.category)+'</b><small>'+esc(x.description||'Investment')+' · '+esc(x.account||'No account')+' · '+esc(String(x.occurred_on).slice(0,10))+'</small></div><span class="value">'+money(x.amount)+'</span></div>').join('')+'</div>':'<p class="muted">No investment transactions have been recorded yet. Existing records are preserved.</p>')+'<h3 class="group-title">Imported investment records</h3>'+(records.length?mergedOtherHtml(records):'<p class="muted">No imported investment or portfolio snapshots found.</p>')+fixedDepositsHtml();}else if(view==='bank-detail'){const key=activeBank||'Bank';$('viewTitle').textContent=key;target.innerHTML='<button type="button" class="back-button" id="backToBanks">← All accounts</button><h3 class="group-title">'+esc(key)+' account details</h3>'+accountRecords(key).map(sectionHtml).join('')}else if(view==='transactions'){target.innerHTML='<section class="card history"><div class="historyhead"><div><div class="eyebrow">LIVE LEDGER</div><h3>Recorded transactions</h3></div><span class="pill">'+items.length+' entries</span></div><div class="entries">'+$('entries').innerHTML+'</div></section>'}const bindSpendCard=(selector,isMonth)=>{const card=target.querySelector(selector);if(card){const toggle=()=>{if(isMonth)showMonthSpend=!showMonthSpend;else showCategorySpend=!showCategorySpend;renderView('overview')};card.addEventListener('click',toggle);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})}};bindSpendCard('[data-spend-breakdown]',false);bindSpendCard('[data-month-spend-breakdown]',true)}
$('viewContent').addEventListener('click',e=>{if(e.target.closest('[data-angel-refresh]')){loadAngelOne();return}const fdForm=e.target.closest('#fdForm');if(fdForm){e.preventDefault();const fdMsg=$('fdMsg');const form=new FormData(fdForm);const payload=Object.fromEntries(form.entries());fdMsg.textContent='Saving FD…';api('/api/positions',{method:'POST',body:JSON.stringify(payload)}).then(async()=>{await loadDashboard();renderTopWealth();renderView('investments')}).catch(err=>{fdMsg.textContent=err.message});return}const point=e.target.closest('[data-chart-point]');if(point){const box=point.closest('.chart-interactive');if(box){box.querySelectorAll('.chart-point').forEach(p=>p.classList.remove('selected'));point.classList.add('selected');const tip=box.querySelector('.chart-tooltip');if(tip){tip.innerHTML='<b>'+point.dataset.chartValue+'</b><span>'+point.dataset.chartLabel+'</span>';tip.hidden=false;}}return}const paid=e.target.closest('[data-bill-paid]');if(paid){const id=paid.dataset.billPaid;api('/api/planned-bills',{method:'PATCH',body:JSON.stringify({id,status:'paid'})}).then(()=>{plannedBills=plannedBills.filter(b=>b.id!==id);renderView(activeView)}).catch(err=>{$('globalMsg').textContent=err.message});return}if(e.target.closest('[data-spend-close]')){showCategorySpend=false;showMonthSpend=false;renderView('overview');return}const card=e.target.closest('[data-bank]');if(card){openBank(card.dataset.bank);return}if(e.target.closest('#backToBanks'))renderView('banks')});
$('menuNav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)renderView(b.dataset.view)});
$('mobileNav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)renderView(b.dataset.view)});

if($('logout'))$('logout').onclick=async()=>{try{await api('/api/auth?action=logout',{method:'POST',body:'{}'});}finally{location.reload()}};
$('cancel').onclick=()=>$('txForm').classList.add('hidden');
$('txForm').onsubmit=async e=>{e.preventDefault();$('txMsg').textContent='';try{await api('/api/ledger',{method:'POST',body:JSON.stringify({kind:$('kind').value,amount:$('amount').value,category:$('category').value,account:$('account').value,date:$('date').value,description:$('description').value})});e.target.reset();$('txForm').classList.add('hidden');await load();renderView(activeView)}catch(x){$('txMsg').textContent=x.message}};
(async()=>{try{const d=await api('/api/auth');if(d.user){user=d.user;await showApp()}else{$('auth').classList.remove('hidden')}}catch(e){$('auth').classList.remove('hidden');$('globalMsg').textContent='Account verification failed: '+(e?.message||'Please try again.');console.error('[wealth-startup:auth]',e)}})();

